responsePreview:
This Terraform configuration creates an AWS Route 53 hosted zone named `main`, an RDS MySQL primary database instance named `primary`, and two RDS read replicas named `replica-1` and `replica-2`. It then creates two weighted Route 53 CNAME records under `db.main`, splitting traffic evenly between the two replica database endpoints.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_password" {
  length  = 16
  special = false
}

resource "aws_route53_zone" "main" {
  name = "main"
}

resource "aws_db_instance" "primary" {
  identifier = "primary-${random_id.suffix.hex}"

  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp2"

  db_name  = "maindb"
  username = "adminuser"
  password = random_password.db_password.result

  backup_retention_period = 1

  publicly_accessible = false
  skip_fi

