    vpc_id = aws_vpc.verification_vpc.id
  }

  tags = {
    Name = "example"
  }
}

resource "aws_route53_record" "ownership_verification" {
  zone_id = aws_route53_zone.example.zone_id
  name    = aws_route53_zone.example.name
  type    = "TXT"
  ttl     = 300

  records = [
    "\"passwordpassword\""
  ]
}
