  description = "Name of the Amazon Kinesis stream"
  type        = string
  default     = "basic-kinesis-stream"
}

resource "aws_kinesis_stream" "basic" {
  name             = var.stream_name
  shard_count      = 1
  retention_period = 24

  shard_level_metrics = [
    "IncomingBytes",
    "OutgoingBytes"
  ]

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = {
    Name        = var.stream_name
    Environment = "example"
  }
}

output "kinesis_stream_name" {
  description = "The name of the Kinesis stream"
  value       = aws_kinesis_stream.basic.name
}

output "kinesis

